@RestController
public class DiagnosticController {

    @GetMapping("/devtools/status")
    public ResponseEntity<String> checkDevToolsStatus() {
        // DevTools runs only when not packaged as a production jar.
        // ClassLoader identification confirms the dual-classloader setup.
        ClassLoader cl = this.getClass().getClassLoader();
        String loaderName = cl.getClass().getSimpleName();

        return ResponseEntity.ok(
            "Active ClassLoader: " + loaderName + " | LiveReload active and listening."
        );
    }
}
